// ── LOCAL DICTIONARY ─────────────────────────────────────────
// dict.js sets self.DICT; generated by: node scripts/build-dict.js
try { importScripts('dict.js'); } catch (_) {}

// ── SETUP ────────────────────────────────────────────────────
chrome.runtime.onInstalled.addListener(async () => {
  chrome.contextMenus.create({
    id: 'sip-lookup',
    title: 'Sip this word ☕',
    contexts: ['selection'],
  });
  await rescheduleReminder();
  await updateBadge();
});

// ── CONTEXT MENU ─────────────────────────────────────────────
chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId !== 'sip-lookup' || !info.selectionText) return;
  const word = info.selectionText.trim().split(/\s+/)[0]; // first word only
  if (!word) return;
  chrome.tabs.sendMessage(tab.id, { type: 'CONTEXT_LOOKUP', word });
});

// ── DAILY REMINDER ───────────────────────────────────────────
chrome.alarms.onAlarm.addListener(async (alarm) => {
  if (alarm.name !== 'sip-daily-reminder') return;
  const r = await chrome.storage.local.get(['sip-settings', 'sip-words']);
  const settings = r['sip-settings'] || {};
  if (!settings.reminderEnabled) return;
  const words = r['sip-words'] || [];
  const due = words.filter(w => !w.nextReview || w.nextReview <= Date.now()).length;
  if (due > 0) {
    chrome.notifications.create({
      type: 'basic',
      iconUrl: 'icons/icon128.png',
      title: 'Sip ☕ — Time to review!',
      message: `You have ${due} word${due !== 1 ? 's' : ''} ready. Take 5 minutes to brew! ☕`,
    });
  }
  await rescheduleReminder();
  await updateBadge();
});

// ── REMINDER SCHEDULER ───────────────────────────────────────────────────────
async function rescheduleReminder() {
  const r = await chrome.storage.local.get('sip-settings');
  const s = r['sip-settings'] || {};
  await chrome.alarms.clear('sip-daily-reminder');
  if (!s.reminderEnabled) return;
  const [h, m] = (s.reminderTime || '09:00').split(':').map(Number);
  const now  = Date.now();
  const next = new Date();
  next.setHours(h, m, 0, 0);
  if (next.getTime() <= now) next.setDate(next.getDate() + 1);
  chrome.alarms.create('sip-daily-reminder', {
    when: next.getTime(),
    periodInMinutes: 1440,
  });
}

// ── MESSAGE ROUTER ────────────────────────────────────────────
const reply = (fn, sendResponse) => fn().then(sendResponse).catch(e => sendResponse({ error: e.message }));

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === 'LOOKUP')             { reply(() => handleLookup(msg.word, msg.lang || 'en'), sendResponse); return true; }
  if (msg.type === 'AI_EXAMPLE')         { reply(() => handleAiExample(msg), sendResponse);                return true; }
  if (msg.type === 'SAVE_WORD')          { reply(() => handleSaveWord(msg.wordData), sendResponse);        return true; }
  if (msg.type === 'UPDATE_WORD')        { reply(() => handleUpdateWord(msg.wordData), sendResponse);      return true; }
  if (msg.type === 'REMOVE_WORD')        { reply(() => handleRemoveWord(msg.word), sendResponse);          return true; }
  if (msg.type === 'CHECK_SAVED')        { reply(() => handleCheckSaved(msg.word, msg.lang || 'en'), sendResponse); return true; }
  if (msg.type === 'TEST_AI')            { reply(() => handleTestAi(msg), sendResponse);                    return true; }
  if (msg.type === 'MUSIC_STREAM_START') { reply(() => handleMusicStreamStart(msg.url), sendResponse);    return true; }
  if (msg.type === 'MUSIC_STREAM_STOP')  { reply(() => handleMusicStreamStop(), sendResponse);             return true; }
  if (msg.type === 'MUSIC_VOLUME')       { reply(() => handleMusicVolume(msg.volume), sendResponse);       return true; }
  if (msg.type === 'RESCHEDULE_REMINDER') { reply(() => rescheduleReminder().then(() => ({ ok:true })), sendResponse); return true; }
  if (msg.type === 'UPDATE_BADGE')        { reply(() => updateBadge().then(() => ({ ok: true })), sendResponse);         return true; }
  if (msg.type === 'BREW_STORY')          { reply(() => handleBrewStory(msg), sendResponse);                              return true; }
  if (msg.type === 'MEMORY_HOOK')         { reply(() => handleMemoryHook(msg), sendResponse);                              return true; }
  if (msg.type === 'WORD_ROOTS')          { reply(() => handleWordRoots(msg), sendResponse);                               return true; }
});

// ── AI PRIMITIVE ──────────────────────────────────────────────

async function callAi(prompt, cfg, { maxTokens = 300, temperature = 0.3, timeoutMs = 8000 } = {}) {
  const base = (cfg.apiUrl || '').trim().replace(/\/$/, '');
  if (!base) return null;
  const ctrl  = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (cfg.apiKey) headers['Authorization'] = `Bearer ${cfg.apiKey}`;
    const res = await fetch(`${base}/v1/chat/completions`, {
      method:  'POST',
      headers,
      body:    JSON.stringify({
        model:       cfg.apiModel?.trim() || 'default',
        messages:    [{ role: 'user', content: prompt }],
        max_tokens:  maxTokens,
        temperature,
      }),
      signal: ctrl.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    return (data.choices?.[0]?.message?.content ?? '').trim();
  } catch (_) {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// ── LEMMATIZER ───────────────────────────────────────────────
function lemmatize(word) {
  const w = word.toLowerCase();
  const c = [];
  if (w.endsWith('ing') && w.length > 5) {
    const s = w.slice(0, -3);
    if (s.length >= 3 && s.at(-1) === s.at(-2)) c.push(w.slice(0, -4));
    c.push(s + 'e', s);
  } else if (w.endsWith('ied') && w.length > 5) {
    c.push(w.slice(0, -3) + 'y');
  } else if (w.endsWith('ed') && w.length > 4) {
    const s = w.slice(0, -2);
    if (s.length >= 3 && s.at(-1) === s.at(-2)) c.push(w.slice(0, -3));
    c.push(s + 'e', s);
  } else if (w.endsWith('ies') && w.length > 4) {
    c.push(w.slice(0, -3) + 'y');
  } else if (w.endsWith('es') && w.length > 4) {
    c.push(w.slice(0, -2), w.slice(0, -1));
  } else if (w.endsWith('s') && w.length > 3 && !w.endsWith('ss')) {
    c.push(w.slice(0, -1));
  } else if (w.endsWith('ly') && w.length > 4) {
    c.push(w.slice(0, -2), w.slice(0, -2) + 'e');
  } else if (w.endsWith('er') && w.length > 4 && !w.endsWith('eer') && !w.endsWith('ier')) {
    const s = w.slice(0, -2);
    if (s.length >= 3 && s.at(-1) === s.at(-2)) c.push(w.slice(0, -3));
    c.push(s, s + 'e');
  } else if (w.endsWith('est') && w.length > 5) {
    c.push(w.slice(0, -3), w.slice(0, -2));
  }
  return [...new Set(c.filter(x => x.length >= 2 && x !== w))];
}

// ── WIKTIONARY LOOKUP (Finnish / Swedish) ────────────────────
async function fetchWiktionary(word, lang) {
  const ctrl  = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 4000);
  try {
    const res = await fetch(
      `https://en.wiktionary.org/api/rest_v1/page/definition/${encodeURIComponent(word.toLowerCase())}`,
      { signal: ctrl.signal }
    );
    clearTimeout(timer);
    if (!res.ok) return null;
    const data    = await res.json();
    const entries = data[lang];
    if (!entries?.length) return null;
    const entry = entries[0];
    const def   = entry.definitions?.[0];
    if (!def?.definition) return null;
    const clean = s => (s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    return {
      word,
      phonetic:   '',
      audioUrl:   '',
      pos:        (entry.partOfSpeech || '').toLowerCase(),
      definition: clean(def.definition),
      example:    clean(def.parsedExamples?.[0]?.example || def.example || ''),
      synonyms:   [],
      antonyms:   [],
      lang,
    };
  } catch (_) { clearTimeout(timer); return null; }
}

// ── DICTIONARY LOOKUP ─────────────────────────────────────────
async function handleLookup(rawWord, lang = 'en') {
  const word     = rawWord.toLowerCase().trim();
  const cacheKey = `${lang}:${word}`;

  const [sr, cr] = await Promise.all([
    chrome.storage.local.get('sip-settings'),
    chrome.storage.local.get('sip-dict-cache'),
  ]);
  const cfg        = sr['sip-settings'] ?? {};
  const cache      = cr['sip-dict-cache'] ?? {};
  const aiAvailable = !!cfg.apiUrl;

  // Instant cache hit
  if (cache[cacheKey]) return { ...cache[cacheKey], aiAvailable };

  // Local dictionary hit (English only)
  if (lang === 'en' && typeof DICT !== 'undefined') {
    const localEntry = DICT[word] ?? DICT[lemmatize(word).find(l => DICT[l])];
    if (localEntry) {
      return {
        word:       rawWord,
        phonetic:   '',
        audioUrl:   '',
        pos:        localEntry.p || '',
        definition: localEntry.d,
        example:    localEntry.e || '',
        synonyms:   localEntry.s || [],
        antonyms:   [],
        lang:       'en',
        aiAvailable,
      };
    }
  }

  async function fetchDictEntry(w, dictLang = 'en') {
    const ctrl  = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 3000);
    try {
      const res = await fetch(
        `https://api.dictionaryapi.dev/api/v2/entries/${dictLang}/${encodeURIComponent(w)}`,
        { signal: ctrl.signal }
      );
      clearTimeout(timer);
      if (!res.ok) return null;
      const [entry] = await res.json();
      if (!entry) return null;
      const meaning   = entry.meanings?.[0] ?? {};
      const def       = meaning.definitions?.[0] ?? {};
      const phonetics = entry.phonetics ?? [];
      return {
        word:       entry.word,
        phonetic:   phonetics.find(p => p.text)?.text ?? entry.phonetic ?? '',
        audioUrl:   phonetics.find(p => p.audio && p.audio.startsWith('http'))?.audio ?? '',
        pos:        meaning.partOfSpeech ?? '',
        definition: def.definition ?? '',
        example:    def.example ?? '',
        synonyms:   [...(def.synonyms ?? []), ...(meaning.synonyms ?? [])].filter(Boolean).slice(0, 5),
        antonyms:   [...(def.antonyms ?? []), ...(meaning.antonyms ?? [])].filter(Boolean).slice(0, 3),
        lang:       dictLang,
      };
    } catch (_) { clearTimeout(timer); return null; }
  }

  async function fetchForLang() {
    if (lang === 'fi' || lang === 'sv') {
      let r = await fetchWiktionary(word, lang);
      // Try capitalised form (nominative case for nouns)
      if (!r) {
        const cap = word.charAt(0).toUpperCase() + word.slice(1);
        if (cap !== word) r = await fetchWiktionary(cap, lang);
      }
      return r;
    }
    if (lang === 'es') return fetchDictEntry(word, 'es');
    // English: try with lemma fallbacks
    let r = await fetchDictEntry(word, 'en');
    if (!r) {
      for (const lemma of lemmatize(word)) {
        r = await fetchDictEntry(lemma, 'en');
        if (r) break;
      }
    }
    return r;
  }

  async function fetchFromAi() {
    if (!aiAvailable) return null;
    const langNames = { en: 'English', es: 'Spanish', fi: 'Finnish', sv: 'Swedish' };
    const langName  = langNames[lang] || 'English';
    const prompt = `Define the ${langName} word "${rawWord}". Return ONLY valid JSON (no markdown, no extra text) with exactly these fields:\n{"phonetic":"","pos":"noun","definition":"English meaning here","example":"An example sentence in ${langName}.","synonyms":["word1"],"antonyms":[]}`;
    try {
      const raw = await callAi(prompt, cfg, { maxTokens: 300, temperature: 0.2, timeoutMs: 10000 });
      if (!raw) return null;
      const p = JSON.parse(raw.replace(/^```json\s*|\s*```$/g, ''));
      if (!p.definition) return null;
      return {
        word:       rawWord,
        phonetic:   p.phonetic  || '',
        audioUrl:   '',
        pos:        p.pos        || '',
        definition: p.definition,
        example:    p.example    || '',
        synonyms:   (p.synonyms  || []).slice(0, 5),
        antonyms:   (p.antonyms  || []).slice(0, 3),
        lang,
      };
    } catch (_) { return null; }
  }

  // Race primary API against AI — first valid result wins
  const racers = [fetchForLang()];
  if (aiAvailable) racers.push(fetchFromAi());

  const result = await new Promise((resolve) => {
    let done    = false;
    let pending = racers.length;
    racers.forEach(p =>
      p.then(r => {
        if (r && !done)              { done = true; resolve(r); }
        else if (--pending === 0 && !done) { done = true; resolve(null); }
      }).catch(() => { if (--pending === 0 && !done) { done = true; resolve(null); } })
    );
  });

  if (!result) return { error: `"${rawWord}" wasn't found. Try a simpler form of the word.` };

  result.lang = lang;

  // Persist to cache (cap at 500 entries)
  cache[cacheKey] = result;
  const keys = Object.keys(cache);
  if (keys.length > 500) keys.slice(0, keys.length - 500).forEach(k => delete cache[k]);
  await chrome.storage.local.set({ 'sip-dict-cache': cache });

  return { ...result, aiAvailable };
}

// ── AI EXAMPLE ────────────────────────────────────────────────
async function handleAiExample({ word, pos, definition }) {
  try {
    const [sr, wr] = await Promise.all([
      chrome.storage.local.get('sip-settings'),
      chrome.storage.local.get('sip-words'),
    ]);
    const cfg   = sr['sip-settings'] ?? {};
    const words = wr['sip-words'] ?? [];
    const saved = words.find(w => w.word.toLowerCase() === word.toLowerCase());
    if (saved?.aiExample) return { example: saved.aiExample };

    const prompt = `Write one warm, memorable example sentence using the English word "${word}" (${pos}: ${definition}). Make it natural, slightly creative, easy to remember — like a line from a good novel. Return only the sentence, no quotes, no explanation.`;
    const text   = await callAi(prompt, cfg, { maxTokens: 120, temperature: 0.7, timeoutMs: 8000 });
    if (!text) return { example: null };

    if (saved) {
      const idx = words.findIndex(w => w.word.toLowerCase() === word.toLowerCase());
      if (idx >= 0) {
        words[idx].aiExample = text;
        await chrome.storage.local.set({ 'sip-words': words });
      }
    }
    return { example: text };
  } catch (_) {
    return { example: null };
  }
}

// ── MEMORY HOOK ───────────────────────────────────────────────
async function handleMemoryHook({ word, pos, definition, lang }) {
  try {
    const [sr, wr] = await Promise.all([
      chrome.storage.local.get('sip-settings'),
      chrome.storage.local.get('sip-words'),
    ]);
    const cfg   = sr['sip-settings'] ?? {};
    if (!cfg.apiUrl) return { hook: null };
    const words = wr['sip-words'] ?? [];
    const saved = words.find(w => w.word.toLowerCase() === word.toLowerCase() && (w.lang || 'en') === lang);
    if (saved?.memoryHook) return { hook: saved.memoryHook };
    const langNames = { en: 'English', es: 'Spanish', fi: 'Finnish', sv: 'Swedish' };
    const langName  = langNames[lang] || 'English';
    const prompt = `Create a fun, vivid mnemonic or memory hook to help remember the ${langName} word "${word}" (${pos}: ${definition}). Use a memorable image, story, or wordplay — 1-2 sentences. Return only the hook, no preamble.`;
    const text = await callAi(prompt, cfg, { maxTokens: 150, temperature: 0.8, timeoutMs: 8000 });
    if (!text) return { hook: null };
    const idx = words.findIndex(w => w.word.toLowerCase() === word.toLowerCase() && (w.lang || 'en') === lang);
    if (idx >= 0) { words[idx].memoryHook = text; await chrome.storage.local.set({ 'sip-words': words }); }
    return { hook: text };
  } catch (_) { return { hook: null }; }
}

// ── WORD ROOTS ────────────────────────────────────────────────
async function handleWordRoots({ word, definition }) {
  try {
    const [sr, wr] = await Promise.all([
      chrome.storage.local.get('sip-settings'),
      chrome.storage.local.get('sip-words'),
    ]);
    const cfg   = sr['sip-settings'] ?? {};
    if (!cfg.apiUrl) return { roots: null };
    const words = wr['sip-words'] ?? [];
    const saved = words.find(w => w.word.toLowerCase() === word.toLowerCase());
    if (saved?.wordRoots) return { roots: saved.wordRoots };
    const prompt = `Analyze the word roots and affixes of "${word}" (${definition}). Return ONLY valid JSON (no markdown): {"roots":[{"part":"re","origin":"Latin","meaning":"again"}]}. Include 1-4 meaningful parts. If no interesting etymology exists, return {"roots":[]}.`;
    const raw = await callAi(prompt, cfg, { maxTokens: 200, temperature: 0.2, timeoutMs: 8000 });
    if (!raw) return { roots: null };
    const p = JSON.parse(raw.replace(/^```json\s*|\s*```$/g, ''));
    if (!Array.isArray(p.roots)) return { roots: null };
    const idx = words.findIndex(w => w.word.toLowerCase() === word.toLowerCase());
    if (idx >= 0) { words[idx].wordRoots = p.roots; await chrome.storage.local.set({ 'sip-words': words }); }
    return { roots: p.roots };
  } catch (_) { return { roots: null }; }
}

// ── AI TEST ───────────────────────────────────────────────────
async function handleTestAi(msg = {}) {
  const cfg     = (await chrome.storage.local.get('sip-settings'))['sip-settings'] ?? {};
  const baseUrl = (msg.url ?? cfg.apiUrl ?? '').trim().replace(/\/$/, '');
  const authKey = msg.key !== undefined ? msg.key : (cfg.apiKey ?? '');
  let   model   = (msg.model ?? cfg.apiModel ?? '').trim();

  if (!baseUrl) return { ok: false, error: 'No URL — enter the server address first' };

  try {
    if (!model) {
      const mr = await fetch(`${baseUrl}/v1/models`, {
        headers: authKey ? { 'Authorization': `Bearer ${authKey}` } : {},
      }).catch(() => null);
      if (mr?.ok) {
        const md = await mr.json().catch(() => ({}));
        model = md.data?.[0]?.id || '';
      }
    }

    const headers = { 'Content-Type': 'application/json' };
    if (authKey) headers['Authorization'] = `Bearer ${authKey}`;
    const res = await fetch(`${baseUrl}/v1/chat/completions`, {
      method: 'POST', headers,
      body: JSON.stringify({
        model: model || 'default',
        messages: [{ role: 'user', content: 'Reply with only the word: ok' }],
        max_tokens: 10, temperature: 0,
      }),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      return { ok: false, error: body.error?.message || body.message || `HTTP ${res.status}` };
    }
    return { ok: true, modelUsed: model || undefined };
  } catch (e) {
    const low = (e.message || '').toLowerCase();
    return { ok: false, error: low.includes('fetch') || low.includes('failed')
      ? `Not reachable — is the server running at ${baseUrl}?` : e.message };
  }
}

// ── MUSIC STREAM ──────────────────────────────────────────────
async function ensureOffscreen() {
  const existing = await chrome.runtime.getContexts({ contextTypes: ['OFFSCREEN_DOCUMENT'] }).catch(() => []);
  if (existing.length > 0) return;
  await chrome.offscreen.createDocument({
    url: 'offscreen.html',
    reasons: ['AUDIO_PLAYBACK'],
    justification: 'Play ambient background music',
  });
}

async function handleMusicStreamStart(url) {
  try {
    await ensureOffscreen();
    await new Promise(resolve => setTimeout(resolve, 250));
    const r = await chrome.storage.local.get('sip-settings');
    const volume = r['sip-settings']?.volume ?? 0.4;
    chrome.runtime.sendMessage({ target: 'offscreen', type: 'STREAM_PLAY', url, volume }).catch(() => {});
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

async function handleMusicStreamStop() {
  chrome.runtime.sendMessage({ target: 'offscreen', type: 'STREAM_STOP' }).catch(() => {});
  await chrome.offscreen.closeDocument().catch(() => {});
  return { ok: true };
}

async function handleMusicVolume(volume) {
  chrome.runtime.sendMessage({ target: 'offscreen', type: 'STREAM_VOLUME', volume }).catch(() => {});
  return { ok: true };
}

// ── SAVE WORD ─────────────────────────────────────────────────
async function handleSaveWord(wordData) {
  const r = await chrome.storage.local.get('sip-words');
  const words   = r['sip-words'] ?? [];
  const wLang   = wordData.lang || 'en';

  if (words.some(w => w.word.toLowerCase() === wordData.word.toLowerCase() && (w.lang || 'en') === wLang)) {
    return { saved: false, reason: 'already_exists' };
  }

  const newWord = {
    ...wordData,
    id:          crypto.randomUUID(),
    addedAt:     Date.now(),
    repetitions: 0,
    easeFactor:  2.5,
    interval:    0,
    nextReview:  Date.now(),
  };

  words.unshift(newWord);
  await chrome.storage.local.set({ 'sip-words': words });
  updateBadge().catch(() => {});

  // Notify popup if open
  chrome.runtime.sendMessage({ type: 'WORD_ADDED', word: newWord.word }).catch(() => {});

  return { saved: true };
}

async function handleUpdateWord(wordData) {
  if (!wordData?.word) return { ok: false };
  const r     = await chrome.storage.local.get('sip-words');
  const words = r['sip-words'] ?? [];
  const idx   = words.findIndex(w => w.word.toLowerCase() === wordData.word.toLowerCase());
  if (idx < 0) return { ok: false };
  const existing = words[idx];
  words[idx] = {
    ...existing,
    ...wordData,
    // preserve spaced-repetition and identity fields
    id:          existing.id,
    addedAt:     existing.addedAt,
    repetitions: existing.repetitions,
    easeFactor:  existing.easeFactor,
    interval:    existing.interval,
    nextReview:  existing.nextReview,
    aiExample:   existing.aiExample,
  };
  await chrome.storage.local.set({ 'sip-words': words });
  return { ok: true };
}

async function handleRemoveWord(word) {
  if (!word) return { removed: false };
  const r     = await chrome.storage.local.get('sip-words');
  const words = r['sip-words'] ?? [];
  const next  = words.filter(w => w.word.toLowerCase() !== word.toLowerCase());
  if (next.length === words.length) return { removed: false };
  await chrome.storage.local.set({ 'sip-words': next });
  updateBadge().catch(() => {});
  chrome.runtime.sendMessage({ type: 'WORD_REMOVED', word }).catch(() => {});
  return { removed: true };
}

async function handleCheckSaved(word, lang = 'en') {
  const r = await chrome.storage.local.get('sip-words');
  const words = r['sip-words'] ?? [];
  return { saved: words.some(w => w.word.toLowerCase() === word.toLowerCase() && (w.lang || 'en') === lang) };
}

// ── BADGE ─────────────────────────────────────────────────────
async function updateBadge() {
  const r    = await chrome.storage.local.get('sip-words');
  const words = r['sip-words'] ?? [];
  const due  = words.filter(w => !w.nextReview || w.nextReview <= Date.now()).length;
  if (due > 0) {
    chrome.action.setBadgeText({ text: String(due) });
    chrome.action.setBadgeBackgroundColor({ color: '#FF2D6B' });
  } else {
    chrome.action.setBadgeText({ text: '' });
  }
}

// ── BREW STORY ────────────────────────────────────────────────
async function handleBrewStory({ regenerate = false } = {}) {
  const now    = new Date();
  const dateKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  const cacheKey = `sip-brew-${dateKey}`;

  if (!regenerate) {
    const cached = await chrome.storage.local.get(cacheKey);
    if (cached[cacheKey]) return cached[cacheKey];
  }

  const r    = await chrome.storage.local.get(['sip-words', 'sip-settings']);
  const words = r['sip-words'] ?? [];
  const cfg   = r['sip-settings'] ?? {};
  if (!cfg.apiUrl) return null;

  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);
  const todayWords = words.filter(w => w.addedAt >= todayStart.getTime());
  if (todayWords.length < 3) return null;

  const wordList = todayWords.map(w => `"${w.word}"`).join(', ');
  const prompt   = `You're a creative writer with a wicked sense of humor. Write a short, funny, memorable story (3-4 sentences) that naturally uses ALL of these English vocabulary words: ${wordList}. Make it absurd, unexpected, and laugh-out-loud funny. Return ONLY the story, no title, no explanation. Bold each vocabulary word by wrapping it in **double asterisks** like **this**.`;

  const story = await callAi(prompt, cfg, { maxTokens: 300, temperature: 0.9, timeoutMs: 15000 });
  if (!story) return null;

  const result = { story, words: todayWords.map(w => w.word), dateKey };
  await chrome.storage.local.set({ [cacheKey]: result });
  return result;
}
